starter:
%dw 2.0
output application/json
---
payload reduce ((r, acc = {ok: [], failed: []}) ->
  if (r.value != null and !isEmpty(r.value))
    acc update { case .ok -> $ ++ [{id: r.id, value: r.value as Number}] }
  else
    acc update { case .failed -> $ ++ [r.id] }
)

solution:
%dw 2.0
import * from dw::Runtime
output application/json
var results = payload map (r) -> { id: r.id, t: try(() -> r.value as Number) }
---
{
  ok: (results filter ($.t.success)) map { id: $.id, value: $.t.result },
  failed: (results filter (!$.t.success)) map $.id
}

